const parent = element.parentNode;
if (parent.querySelector('.cta-contact-button')) return;

const wrapper = document.createElement('div');
wrapper.className = 'cta-contact-button';
wrapper.style.marginTop = '16px';
wrapper.style.width = 'fit-content';

const button = document.createElement('a');
button.href = 'https://support.fandom.com/hc/en-us/requests/new?ticket_form_id=360000931354&tf_360017817454=i_want_a_feature_or_extension_turned_on';
button.textContent = 'Request a Feature or Extension';
button.style.display = 'inline-block';
button.style.padding = '12px 28px';
button.style.backgroundColor = '#520044';
button.style.color = '#ffffff';
button.style.textDecoration = 'none';
button.style.borderRadius = '6px';
button.style.fontWeight = 'bold';
button.style.fontSize = '16px';
button.style.textAlign = 'center';
button.style.border = 'none';
button.style.cursor = 'pointer';
button.style.transition = 'background-color 0.2s ease';

wrapper.appendChild(button);
element.parentNode.insertBefore(wrapper, element.nextSibling);
